code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            objects.append((color, cells))
    # Repeatedly let every rigid object move one cell right when unobstructed.
    while True:
        occupied = {cell for _, cells in objects for cell in cells}
        moving = []
        for i, (_, cells) in enumerate(objects):
            dest = {(r, c+1) for r, c in cells}
            if all(c+1 < w and ((r,c+1) not in occupied or (r,c+1) in set(cells)) for r,c in cells):
                moving.append(i)
        if not moving:
            break
        moving_set = set(moving)
        objects = [(color, [(r,c+1) for r,c in cells] if i in moving_set else cells)
                   for i,(color,cells) in enumerate(objects)]
    for r in range(h):
        for c in range(w):
            out[r][c] = 0
    for color, cells in objects:
        for r,c in cells:
            out[r][c] = color
    return out
'''
